         sycl::nd_range<1>(sycl::range<1>(G * L), sycl::range<1>(L)),
         [=](sycl::nd_item<1> it) {
           auto grp = it.get_group();
           int idx = (int)it.get_group(0);
           int lid = (int)it.get_local_id(0);
           int BT = B * T;
